mapper.update:
UPDATE exchange_rates AS ex
SET ex.modified = NOW(),
    ex.modified_by = #{exchangeRate.modifiedBy}
WHERE ex.id = (
  SELECT id
  FROM (
         SELECT id
         FROM exchange_rates
         WHERE currency_center_id = #{exchangeRate.currencyCenterId}
         ORDER BY id DESC
           LIMIT 1
       ) AS temp
);

